import { Component, signal } from '@angular/core';
import { RouterOutlet } from '@angular/router';

@Component({
  selector: 'app-root',
  imports: [RouterOutlet],
  templateUrl: './app.html',
  styleUrl: './app.scss'
})
export class App {
  protected readonly title = signal('storybook');
}

import { CommonModule } from '@angular/common';
import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'app-autocomplete',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './autocomplete.component.html',
  styleUrl: './autocomplete.component.scss',
})
export class AutocompleteComponent {
  @Input() suggestions: string[] = [];
  @Input() placeholder = '';
  @Input() value = '';

  @Output() onInput = new EventEmitter<string>();
  @Output() onSelect = new EventEmitter<string>();

  public filtered: string[] = [];

  onChange(ev: Event) {
    const v = (ev.target as HTMLInputElement).value;
    this.value = v;
    this.filtered = this.suggestions.filter(s => s.toLowerCase().includes(v.toLowerCase()));
    this.onInput.emit(v);
  }

  select(item: string) {
    this.value = item;
    this.filtered = [];
    this.onSelect.emit(item);
  }
}

import { CommonModule } from '@angular/common';
import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'app-button',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './button.component.html',
  styleUrl: './button.component.scss',
})
export class ButtonComponent {
  /** Is this the principal call to action on the page? */
  @Input()
  primary = false;

  /** What background color to use */
  @Input()
  backgroundColor?: string;

  /** How large should the button be? */
  @Input()
  size: 'small' | 'medium' | 'large' = 'medium';

  /**
   * Button contents
   *
   * @required
   */
  @Input()
  label = 'Button';

  /** Optional click handler */
  @Output()
  onClick = new EventEmitter<Event>();

  public get classes(): string[] {
    const mode = this.primary ? 'app-button--primary' : 'app-button--secondary';

    return ['app-button', `app-button--${this.size}`, mode];
  }
}

